//! 6510 disassembler: complete table of the 256 opcodes (legal and illegal).
//! Generated by tools/gen_disasm.py — do not edit by hand.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Mode { Imp, Acc, Imm, Zp, Zpx, Zpy, Abs, Abx, Aby, Ind, Izx, Izy, Rel }

impl Mode {
    /// Total instruction length in bytes (opcode included).
    pub fn len(self) -> u16 {
        match self {
            Mode::Imp | Mode::Acc => 1,
            Mode::Imm | Mode::Zp | Mode::Zpx | Mode::Zpy | Mode::Izx | Mode::Izy | Mode::Rel => 2,
            Mode::Abs | Mode::Abx | Mode::Aby | Mode::Ind => 3,
        }
    }
}

