/// Disassembled instruction.
pub struct Instr {
    pub addr: u16,
    pub bytes: Vec<u8>,
    pub mnemonic: &'static str,
    pub operand: String,
    pub illegal: bool,
}

impl Instr {
    pub fn len(&self) -> u16 { self.bytes.len() as u16 }

    /// Hex bytes separated by spaces, e.g. "A5 C6".
    pub fn bytes_hex(&self) -> String {
        self.bytes.iter().map(|b| format!("{b:02X}")).collect::<Vec<_>>().join(" ")
    }

    /// "LDA $C6" (mnemonic + operand). Illegal opcodes are in lowercase.
    pub fn text(&self) -> String {
        let m = if self.illegal { self.mnemonic.to_ascii_lowercase() } else { self.mnemonic.to_string() };
        if self.operand.is_empty() { m } else { format!("{m} {}", self.operand) }
    }
}

/// Disassembles the instruction at `pc` using `peek` (side-effect-free read).
pub fn disasm(peek: &dyn Fn(u16) -> u8, pc: u16) -> Instr {
    let op = peek(pc);
    let (mnemonic, mode, illegal) = OPCODES[op as usize];
    let len = mode.len();
    let bytes: Vec<u8> = (0..len).map(|i| peek(pc.wrapping_add(i))).collect();
    let b1 = bytes.get(1).copied().unwrap_or(0);
    let b2 = bytes.get(2).copied().unwrap_or(0);
    let w = u16::from_le_bytes([b1, b2]);
    let operand = match mode {
        Mode::Imp => String::new(),
        Mode::Acc => "A".to_string(),
        Mode::Imm => format!("#${b1:02X}"),
        Mode::Zp  => format!("${b1:02X}"),
        Mode::Zpx => format!("${b1:02X},X"),
        Mode::Zpy => format!("${b1:02X},Y"),
        Mode::Abs => format!("${w:04X}"),
        Mode::Abx => format!("${w:04X},X"),
        Mode::Aby => format!("${w:04X},Y"),
        Mode::Ind => format!("(${w:04X})"),
        Mode::Izx => format!("(${b1:02X},X)"),
        Mode::Izy => format!("(${b1:02X}),Y"),
        Mode::Rel => {
            let target = pc.wrapping_add(2).wrapping_add(b1 as i8 as u16);
            format!("${target:04X}")
        }
    };
    Instr { addr: pc, bytes, mnemonic, operand, illegal }
}
